def process(load_categories) -> pd.DataFrame:
    imposter = load_categories[load_categories['Category'].str.strip() == 'Imposter Scams']
    if len(imposter) > 0:
        pct_str = imposter['Percentage'].iloc[0].strip()
        pct = float(pct_str.rstrip('%'))
        return pd.DataFrame({'population': ['general'], 'percentage': [pct]})
    return pd.DataFrame({'population': ['general'], 'percentage': [None]})

def load() -> pd.DataFrame:
