def load() -> pd.DataFrame:
    with open('data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Reports_by_Military_Consumers.csv', 'r') as f:
        lines = f.readlines()
    return pd.DataFrame({'line': [line.rstrip('\n') for line in lines]})

def process(parse_military_fraud_categories):
    imposter_row = parse_military_fraud_categories[
        parse_military_fraud_categories['Category'].str.contains('Imposter', case=False, na=False)
    ]
    if len(imposter_row) > 0:
        count = int(imposter_row.iloc[0]['Count'])
    else:
        count = 0
    return pd.DataFrame({'imposter_count': [count]})
